insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 1/1998, de 7 de enero, de Política Lingüística (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-2989', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
