insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 5/1994, de 4 de mayo, de regulación de los servicios de prevención y extinción de incendios y de salvamentos de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t06-llei-bombers-proteccio-civil', 'Tema 6. Llei 5/1994, de serveis de prevenció i extinció d''incendis i de salvaments, i Llei 4/1997, de protecció civil') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t06-llei-bombers-proteccio-civil' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Llei 5/1994: objecte, principis d''actuació i deures de col·laboració ciutadana"},{"n":"2","title":"Personal dels serveis: professionals, voluntaris i bombers d''empresa; condició d''agents de l''autoritat"},{"n":"3","title":"Cos de Bombers de la Generalitat: funcions (art. 13) i organització"},{"n":"4","title":"Escales i categories; accés a bomber de primera"},{"n":"5","title":"Serveis municipals de prevenció i extinció d''incendis"},{"n":"6","title":"Llei 4/1997: objecte, drets i deures, autoprotecció i mesures d''emergència"},{"n":"7","title":"Plans de protecció civil: territorials, especials i d''autoprotecció"},{"n":"8","title":"Estructura: autoritats, CECAT, Comissió de Protecció Civil, municipis"}]'::jsonb, '["§ objecte Llei 5/1994 Llei 5/1994: «La presente Ley tiene por objeto la ordenación general de las acciones y los servicios de prevención y extinción de incendios y de salvamentos en Cataluña»","§ agents de l''autoritat Llei 5/1994: «si están en acto de servicio, tienen la consideración de agentes de la autoridad»","§ coordinació Llei 5/1994: «la máxima autoridad, a efectos de la coordinación de las actuaciones, es el Cuerpo de Bomberos de la Generalidad, a través del mando máximo que intervenga»","§ escala tècnica Llei 5/1994: «Escala técnica, que comprende las categorías de oficial, de sargento, de cabo y de bombero de primera.»","§ protecció civil Llei 4/1997: «Esta Ley regula la protección civil en Cataluña»","§ plans Llei 4/1997: «Los planes de protección civil pueden ser territoriales, especiales y de autoprotección.»","§ CECAT Llei 4/1997: «El CECAT es un órgano Administrativo, sin personalidad jurídica propia, adscrito al Departamento de Gobernación.»","§ municipis Llei 4/1997: «Los municipios son las entidades básicas de la protección civil en Cataluña»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Llei 5/1994: objecte i principis d''actuació","blocks":[{"text":"La Llei 5/1994, de 4 de maig, és la llei catalana que ordena els serveis de prevenció i extinció d''incendis i de salvaments. El seu objecte té quatre peces: l''ordenació general de les accions i dels serveis de prevenció, extinció d''incendis i salvaments a Catalunya; la fixació de l''estructura del Cos de Bombers de la Generalitat; el seu règim estatutari; i la regulació del finançament d''aquests serveis (art. 1).","refs":[{"ref":"Art. 1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"La presente Ley tiene por objeto la ordenación general de las acciones y los servicios de prevención y extinción de incendios y de salvamentos en Cataluña, así como la fijación de la estructura y el régimen estatutari"}]},{"text":"Avís de vigència: el text que es consulta al BOE és una consolidació que el mateix BOE marca com a «desactualitzada», i la llei encara parla del «Departament de Governació». Avui la matèria correspon al Departament d''Interior (vegeu el tema 7), de manera que on la llei diu Governació s''ha d''entendre el departament competent actual. Cal contrastar sempre l''article amb el text consolidat del DOGC o del Portal Jurídic de Catalunya.","refs":[{"ref":"Art. 11.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"El Cuerpo de Bomberos de la Generalidad tiene una estructura y una organización jerarquizadas, a través de los órganos del Departamento de Gobernación que se determinen por reglamento."}]},{"text":"L''article 2 fixa els principis bàsics d''actuació dels membres dels serveis, agrupats en dos blocs. En la relació amb la comunitat han de: respectar els drets fonamentals i les llibertats públiques; actuar amb diligència, celeritat i decisió per aconseguir la màxima rapidesa, i amb proporcionalitat en l''ús dels mitjans; i tractar correctament la ciutadania, auxiliant-la i protegint-la quan calgui.","refs":[{"ref":"Art. 2.a Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Actuar, en el ejercicio de sus funciones, con la diligencia, la celeridad y la decisión necesarias para conseguir la máxima rapidez en la acción y actuar con proporcionalidad en la utilización de los medios a su alcance."}]},{"text":"En les relacions interadministratives, els serveis s''han d''atenir als principis de cooperació, coordinació, col·laboració, solidaritat, assistència recíproca, responsabilitat, complementarietat, subsidiarietat i capacitat d''integració, i han d''actuar amb lleialtat institucional perquè la celeritat de la informació i la transparència de les ordres permetin acabar el sinistre amb el menor cost en vides i béns.","refs":[{"ref":"Art. 2.b Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Atenerse a los principios de cooperación, coordinación, colaboración, solidaridad, asistencia recíproca, responsabilidad, complementariedad, subsidiariedad y capacidad de integración"}]}]},{"n":"2","title":"Deures de col·laboració de la ciutadania","blocks":[{"text":"La ciutadania té l''obligació de col·laborar, personalment i materialment, amb els serveis de prevenció i extinció d''incendis quan ho requereixin les autoritats competents. Aquesta col·laboració pot consistir a complir mesures de prevenció i protecció, participar en simulacres o intervenir operativament en una emergència (art. 3.1).","refs":[{"ref":"Art. 3.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"La ciudadanía tiene la obligación de colaborar, tanto personal como materialmente, con los servicios de prevención y extinción de incendios, a requerimiento de las autoridades competentes."}]},{"text":"Dada clau d''examen: en cas de risc greu, catàstrofe o calamitat pública, la ciutadania ha de complir les prestacions de caràcter personal que determini l''autoritat competent, i aquestes prestacions NO donen dret a indemnització (art. 3.2). En canvi, si l''emergència ho exigeix, les autoritats poden requisar béns i intervenir-los o ocupar-los transitòriament, i les persones afectades SÍ tenen dret a ser indemnitzades (art. 3.3).","refs":[{"ref":"Art. 3.2 i 3.3 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"la ciudadanía está obligada a cumplir las prestaciones de carácter personal que la autoridad competente determine, las cuales no dan derecho a indemnización. […] Las personas afectadas por estas actuaciones tienen derecho a ser indemnizadas"}]},{"text":"Els poders públics han de dissenyar campanyes informatives i formatives per sensibilitzar la ciutadania, i especialment la comunitat educativa, sobre les responsabilitats públiques i la col·laboració necessària en la prevenció i extinció d''incendis (art. 4).","refs":[{"ref":"Art. 4 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Los poderes públicos diseñarán y llevarán a cabo campañas informativas y formativas y demás actividades dirigidas a sensibilizar a la ciudadanía, y especialmente al conjunto de la comunidad educativa"}]}]},{"n":"3","title":"Personal dels serveis: professionals, voluntaris i bombers d''empresa","blocks":[{"text":"Integren els serveis de prevenció i extinció d''incendis i de salvaments de Catalunya: el Cos de Bombers de la Generalitat, el personal dels serveis de les entitats locals, els bombers voluntaris, els bombers d''empresa i el personal tècnic laboral de la disposició addicional tercera (art. 5). El personal pot ser professional o voluntari (art. 6).","refs":[{"ref":"Art. 5 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Integran los servicios de prevención y extinción de incendios y de salvamentos de Cataluña el Cuerpo de Bomberos de la Generalidad, el personal perteneciente a los servicios de prevención y extinción de incendios de las entidades locales, los bomberos voluntarios, los bomberos de empresa"}]},{"text":"El personal professional de la Generalitat té la condició de funcionari i integra el Cos de Bombers de la Generalitat; el dels ens locals és funcionari de l''escala d''administració especial, subescala de serveis especials. Totes dues administracions poden contractar personal laboral per a treballs estacionals o eventuals (art. 7).","refs":[{"ref":"Art. 7.2 i 7.3 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"tiene la condición de funcionario integrado en la escala de administración especial, subescala de servicios especiales. […] pueden contratar personal laboral para trabajos de carácter estacional o eventual."}]},{"text":"Els bombers voluntaris són persones que, per vocació beneficosocial, presten serveis de manera altruista dins l''estructura dels serveis; no són ni personal funcionari ni personal laboral i es regeixen per reglament (art. 51.1). La seva formació correspon a l''Escola de Bombers (art. 51.4), i tenen dret a una assegurança d''accidents en acte de servei, a defensa jurídica i a compensacions per la dedicació (art. 52.1).","refs":[{"ref":"Art. 51.1 i 52.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Los bomberos voluntarios no tienen la consideración de personal funcionario ni de personal laboral y se rigen por la normativa que se establezcan por reglamento. […] tendrán derecho a gozar de un seguro que cubra los accidentes que puedan producirse en acto de servicio"}]},{"text":"Els bombers d''empresa són les persones amb una habilitació expedida per l''Escola de Bombers de Catalunya que les acredita com a tals i que exerceixen funcions de prevenció, extinció i salvament a l''empresa de la qual depenen (art. 9). El departament fixa les condicions de formació i pericia, i l''Escola expedeix l''habilitació (art. 53). Quan el Cos de Bombers intervé en un sinistre que ho requereix, els bombers d''empresa actuen sota la seva coordinació i direcció; si no, sota la del cos municipal corresponent (art. 54.1).","refs":[{"ref":"Art. 9 i 54.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Son bomberos de empresa las personas que tienen una habilitación expedida por la Escuela de Bomberos de Cataluña […] bajo la coordinación y la dirección del Cuerpo de Bomberos de la Generalidad, si el alcance del siniestro lo requiere y éste interviene en el mismo"}]},{"text":"Totes les referències de la llei a l''«Escola de Bombers de Catalunya» s''entenen fetes a l''Escola de Bombers i Seguretat Civil de Catalunya (disposició addicional vuitena).","refs":[{"ref":"DA 8a Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Las referencias que se hacen en la presente Ley a la Escuela de Bomberos de Cataluña se entienden hechas a la Escuela de Bomberos y Seguridad Civil de Cataluña."}]}]},{"n":"4","title":"Condició d''agents de l''autoritat","blocks":[{"text":"En l''exercici de les seves funcions i si estan en acte de servei, els membres del Cos de Bombers de la Generalitat i els dels serveis municipals tenen la consideració d''agents de l''autoritat (no d''autoritat pública ni de policia judicial), a fi de garantir la protecció de les persones i els béns en situacions de perill (art. 10.1).","refs":[{"ref":"Art. 10.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"si están en acto de servicio, tienen la consideración de agentes de la autoridad, a efectos de garantizar la protección de las personas y los bienes en situaciones de peligro."}]},{"text":"A més, el personal professional es considera també en acte de servei quan, tot i estar lliure de servei, intervé en qualsevol tipus de sinistre, sempre que abans acrediti la seva condició (art. 10.2).","refs":[{"ref":"Art. 10.2 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"se considera que está también en acto de servicio si, a pesar de estar libre de servicio, interviene en cualquier tipo de siniestro, previa acreditación de su condición."}]}]},{"n":"5","title":"El Cos de Bombers de la Generalitat: definició, àmbit i funcions","blocks":[{"text":"El Cos de Bombers de la Generalitat té una estructura i una organització jerarquitzades i desenvolupa les funcions de prevenció i extinció d''incendis i de salvaments que corresponen a la Generalitat (art. 11). Actua a Catalunya, si escau en col·laboració amb altres serveis de bombers, i pot actuar fora de Catalunya en supòsits excepcionals o d''emergència, a petició de l''autoritat competent (art. 12).","refs":[{"ref":"Art. 12.2 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"pueden actuar fuera del territorio de Cataluña, en supuestos excepcionales o de emergencia, si la naturaleza del servicio a prestar lo requiere, a petición de la autoridad competente."}]},{"text":"L''article 13 enumera les funcions del Cos: a) extingir incendis i, en qualsevol sinistre o emergència, minimitzar els danys personals i materials; b) fer prevenció (en els municipis sense servei municipal, informar els projectes d''obra i activitats i inspeccionar locals públics); c) estudiar i investigar tècniques, instal·lacions i sistemes de protecció contra incendis; d) intervenir en operacions de protecció civil segons els plans territorials i especials; e) intervenir en salvament marítim, a requeriment de les autoritats; f) intervenir en el salvament fluvial i en el rescat i salvament de muntanya; g) investigar i analitzar els sinistres per informar de causes, conseqüències i danys; h) fer activitats informatives i formatives per augmentar l''autoprotecció; i) actuar en serveis d''interès públic; j) les altres que li atribueixi la legislació.","refs":[{"ref":"Art. 13 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"f) Intervenir en el salvamento fluvial y en el rescate y el salvamento de montaña. […] g) Investigar y analizar los siniestros en los que intervenga por razón de su competencia, para informar sobre las causas y las consecuencias del siniestro y sobre los daños producidos."}]},{"text":"Fixeu-vos que el manteniment de l''ordre públic no figura en aquesta llista: no és una funció del Cos de Bombers. Sí que ho són la prevenció i la formació de la població per limitar les causes i conseqüències dels incendis i dels accidents.","refs":[{"ref":"Art. 13.h Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Llevar a cabo actividades informativas y formativas para la población en general que persigan limitar las causas y las consecuencias de los incendios y de los accidentes y aumentar la autoprotección de la ciudadanía."}]}]},{"n":"6","title":"Comandament, coordinació i escales del Cos","blocks":[{"text":"El comandament i la direcció superior del Cos corresponen a la persona titular del departament (art. 14.1), que en té la direcció, coordinació i inspecció, promou el desplegament territorial, atorga distincions i recompenses i exerceix la potestat disciplinària (art. 14.2).","refs":[{"ref":"Art. 14.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"El mando y la dirección superior del Cuerpo de Bomberos de la Generalidad se ejercen por la persona titular del Departamento de Gobernación."}]},{"text":"Dada clau: en l''extinció d''incendis i en qualsevol sinistre o emergència, la màxima autoritat a l''efecte de coordinar les actuacions és el Cos de Bombers de la Generalitat, a través del comandament màxim que intervingui, sens perjudici del que estableixin els plans d''emergència (art. 14.4).","refs":[{"ref":"Art. 14.4 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"la máxima autoridad, a efectos de la coordinación de las actuaciones, es el Cuerpo de Bomberos de la Generalidad, a través del mando máximo que intervenga, sin perjuicio de lo que se establezca, en su caso, en los correspondientes planes de emergencia."}]},{"text":"El Cos s''estructura en una línia jeràrquica de quatre escales (art. 15): escala superior (inspector); escala executiva (sotsinspector); escala tècnica (oficial, sergent, caporal i bomber de primera); i escala de suport (TECOR, tècnic gestor de sala de coordinació; TEOV, tècnic especialista d''operacions de vol; EPAF, auxiliar tècnic d''equip de prevenció activa forestal; i TELOG, tècnic de gestió logística). L''escala de suport la va afegir el Decret llei 14/2025.","refs":[{"ref":"Art. 15 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Escala técnica, que comprende las categorías de oficial, de sargento, de cabo y de bombero de primera."}]},{"text":"Funcions preferents de cada escala (art. 16): la superior, direcció, coordinació i orientació d''unitats tècniques i operatives de nivell superior; l''executiva, coordinació i comandament d''unitats de nivell intermedi; la tècnica —la de bomber de primera—, les operatives en tasques de prevenció i extinció d''incendis, salvaments i suport sanitari en emergències, i les d''inspecció i de comandament d''unitats operatives i logístiques que determini el reglament; i la de suport, el suport operatiu amb tasques de formació tècnica específica i funcions auxiliars o complementàries.","refs":[{"ref":"Art. 16.1.c Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"En la escala técnica, las operativas en tareas de prevención y extinción de incendios y de salvamentos y de apoyo sanitario en emergencias, y las de inspección y las de mando de unidades operativas y logísticas determinadas por vía reglamentaria."}]}]},{"n":"7","title":"Accés al Cos i accés a bomber de primera","blocks":[{"text":"Per ingressar en cada escala cal la titulació del grup corresponent: superior, grup A; executiva, grup B; tècnica, grup C1; i a l''escala de suport, C1 per a TECOR, TEOV i TELOG i C2 per a EPAF (art. 17.2). Les convocatòries les fa el titular del departament (art. 17.3), i no es pot fixar una edat màxima d''ingrés diferent de la genèrica de la funció pública (art. 17.4).","refs":[{"ref":"Art. 17.2 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"c) Escala técnica, titulación del grupo C1."}]},{"text":"Les proves selectives són de caràcter teoricopràctic i poden incloure proves de capacitat física, mèdiques, psicotècniques i de coneixement (art. 17.6). Durant el curs selectiu, els aspirants són funcionaris en pràctiques, i qui acrediti haver superat un curs de característiques similars en queda exempt (art. 17.5).","refs":[{"ref":"Art. 17.5 i 17.6 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Durante la realización del curso selectivo, las personas aspirantes tienen la consideración de personal funcionario en prácticas. […] Las pruebas selectivas para el acceso a las distintas categorías del Cuerpo de Bomberos de la Generalidad son de carácter teórico-práctico y pueden incluir pruebas de capacidad física, médicas, psico-técnicas y de conocimiento."}]},{"text":"L''accés a bomber de primera es fa per oposició o concurs oposició, en convocatòria lliure, i cal superar a més un curs selectiu a l''Escola (art. 18.1; recordeu que l''Escola és avui l''Escola de Bombers i Seguretat Civil). La Generalitat pot obrir l''accés per concurs als bombers dels ens locals de la mateixa categoria i pot valorar en la fase de concurs el temps prestat com a bomber voluntari (art. 18.2 i 18.3).","refs":[{"ref":"Art. 18 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"El acceso a la categoría de bombero de primera se realiza por oposición o por concurso-oposición, en convocatoria libre. Es necesario superar, además, un curso selectivo […] la valoración en la fase de concurso del tiempo prestado como bombero voluntario de la Generalidad."}]},{"text":"Les categories de caporal, sergent i oficial s''assoleixen per promoció interna, mitjançant concurs oposició, amb un mínim de dos anys d''antiguitat en servei actiu a la categoria immediatament inferior i un curs de capacitació selectiu (art. 19, 20 i 20 bis). A sotsinspector i inspector s''hi accedeix per concurs oposició lliure amb reserva de fins al 65 % de places per a promoció interna (tres anys a la categoria inferior) (art. 21.1).","refs":[{"ref":"Art. 19 i 21.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"tenga un mínimo de dos años de antigüedad de servicio activo en la categoría inmediatamente inferior […] puede acceder a la categoría de cabo por promoción interna, mediante concurso oposición. […] Puede reservarse hasta un 65 por 100 de las plazas de cada convocatoria para la promoción interna"}]},{"text":"L''escala de suport té un règim propi: s''hi accedeix per concurs oposició lliure, amb curs selectiu a l''Institut de Seguretat Pública de Catalunya i període de pràctiques, i des d''aquesta escala NO es pot accedir per promoció interna a la resta d''escales del Cos (art. 17 bis).","refs":[{"ref":"Art. 17 bis Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Desde la escala de apoyo del Cuerpo de Bomberos de la Generalitat no se puede acceder por promoción interna al resto de escalas de este Cuerpo."}]}]},{"n":"8","title":"Organització territorial i serveis municipals de prevenció i extinció d''incendis","blocks":[{"text":"Segons la llei, el Cos s''organitza territorialment en parcs, zones i brigades (art. 24): el parc és el conjunt de mitjans personals i materials, amb organització pròpia, situat en un municipi i amb un àmbit d''intervenció concret; la zona agrupa parcs amb àmbit comarcal; i la brigada agrupa zones. El reglament concreta l''organització (art. 25.4); l''estructura reglamentària actual (regions d''emergències) és al tema 7.","refs":[{"ref":"Art. 24 i 25.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"El Cuerpo de Bomberos de la Generalidad se organiza territorialmente en parques, zonas y brigadas. […] El parque es el conjunto de medios personales y materiales, con organización propia, situado en un municipio y con un ámbito territorial de intervención funcional concreto."}]},{"text":"En els municipis de més de vint mil habitants, la prevenció i l''extinció d''incendis són un servei mínim obligatori (art. 47.1). Aquests municipis poden demanar al Govern la dispensa del servei, i aleshores el presta la Generalitat amb aportació econòmica municipal (art. 47.2 i 47.3); si no presten el servei ni s''acullen a cap fórmula, la Generalitat l''executa subsidiàriament (art. 47.5).","refs":[{"ref":"Art. 47.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"En los municipios de más de veinte mil habitantes, la prevención y la extinción de incendios constituyen un servicio mínimo"}]},{"text":"En els municipis de menys de vint mil habitants que no presten el servei, l''estableix la Generalitat, sens perjudici de la competència municipal per prestar-lo (art. 46). Els alcaldes han de ser informats del desplegament del Cos i de les actuacions que fa en el seu terme (art. 49).","refs":[{"ref":"Art. 46 i 49 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"En los municipios de menos de veinte mil habitantes que no presten el servicio de prevención y extinción de incendios, éste será establecido por la Generalidad […] Los Alcaldes de los municipios afectados serán informados del despliegue del Cuerpo de Bomberos de la Generalidad"}]}]},{"n":"9","title":"Llei 4/1997: objecte, principis i finalitats de la protecció civil","blocks":[{"text":"La Llei 4/1997, de 20 de maig, regula la protecció civil a Catalunya, que comprèn les accions destinades a protegir les persones, els béns i el medi ambient davant de situacions de risc greu col·lectiu, catàstrofes i calamitats públiques (art. 1.1). S''aplica a tot el territori i a totes les emergències, excepte les declarades «d''interès nacional» per la legislació estatal (art. 1.2).","refs":[{"ref":"Art. 1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Esta Ley regula la protección civil en Cataluña, que comprende las acciones destinadas a la protección de las personas, los bienes y el medio ambiente ante situaciones de grave riesgo colectivo, catástrofes y calamidades públicas."}]},{"text":"Avís de vigència: com la Llei 5/1994, el text del BOE de la Llei 4/1997 figura com a consolidació «desactualitzada» i es refereix al conseller o consellera de Governació; avui l''autoritat autonòmica és el conseller o consellera d''Interior, segons el manual oficial del tema 21.","refs":[{"ref":"Manual MAN.GRAL.001","law":"MAN.GRAL.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf","quote":"A nivell autonòmic, l’autoritat de protecció civil és el conseller o consellera d’Interior"}]},{"text":"Principis inspiradors (art. 2.1): solidaritat en l''assumpció de riscos i danys; responsabilitat pública i autoprotecció; proximitat i immediatesa de l''acció pública; i integració de plans i recursos. L''organització s''orienta per la continuïtat, descentralització, planificació, coordinació, subsidiarietat, proporcionalitat, celeritat i eficàcia (art. 2.2).","refs":[{"ref":"Art. 2.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"a) Solidaridad en la asunción de riesgos y daños. b) Responsabilidad pública y autoprotección. c) Proximidad e inmediatez de la acción pública. d) Integración de planes y recursos."}]},{"text":"Les finalitats de l''acció pública (art. 3) segueixen el cicle de la protecció civil: previsió (anàlisi i localització dels riscos), prevenció (disminució i detecció dels riscos), planificació de les respostes, intervenció, restabliment dels serveis essencials i recuperació, preparació dels grups d''intervenció, i informació i formació de la població.","refs":[{"ref":"Art. 3 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"a) La previsión de los riesgos graves, entendida como el análisis objetivo de los mismos y su localización en el territorio. b) La prevención, entendida como el conjunto de actuaciones encaminadas a la disminución de los riesgos así como a su detección inmediata, mediante la vigilancia."}]}]},{"n":"10","title":"Drets i deures, autoprotecció i mesures d''emergència","blocks":[{"text":"La ciutadania té dret a ser informada dels riscos col·lectius greus que la poden afectar i de les mesures públiques (art. 4), a participar en els plans (art. 5) i a col·laborar-hi; i també té el deure de col·laborar, que s''estén als simulacres (art. 6).","refs":[{"ref":"Art. 6.2 i 6.3 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los ciudadanos y ciudadanas tienen el deber de colaborar en las tareas de protección civil […] El deber de colaboración se extiende a los simulacros que organicen las autoridades de protección civil."}]},{"text":"Obligació d''autoprotecció (art. 7): les persones, empreses i entitats que fan activitats que poden generar risc greu col·lectiu, i els centres que en poden resultar especialment afectats, han d''adoptar mesures d''autoprotecció i mantenir els mitjans personals i materials necessaris. Un cop activat un pla, la ciutadania ha de seguir les instruccions de l''autoritat del pla (art. 8.1).","refs":[{"ref":"Art. 7.1 i 8.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"están obligados a la adopción de medidas de autoprotección y a mantener los medios personales y materiales necesarios para hacer frente a situaciones de riesgo y emergencia. […] los ciudadanos y ciudadanas están obligados a seguir las instrucciones y cumplir las órdenes emanadas de la autoridad del plan."}]},{"text":"Mesures d''emergència per a la població que pot acordar l''autoritat (art. 9): evacuar o allunyar les persones dels llocs de perill; recomanar el confinament; restringir l''accés a zones de perill o d''operació; limitar l''ús de serveis i el consum de béns; i les altres que prevegi el pla. Les prestacions personals ordenades són obligatòries i no donen dret a indemnització; les requises sí que s''indemnitzen (art. 10). Els mitjans de comunicació han de difondre gratuïtament i amb prioritat els avisos de l''autoritat (art. 11).","refs":[{"ref":"Art. 9 i 10.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"a) Evacuar o alejar a las personas de los sitios de peligro. b) Recomendar el confinamiento de personas en sus domicilios o en sitios seguros […] La prestación de estos servicios es obligatoria y no da lugar a indemnización por esta causa."}]}]},{"n":"11","title":"Plans de protecció civil","blocks":[{"text":"Els plans de protecció civil poden ser territorials, especials i d''autoprotecció, i s''han de coordinar i integrar entre ells (art. 15). El Pla de protecció civil de Catalunya l''aprova el Govern, a proposta del conseller o consellera competent i amb informe previ de la Comissió de Protecció Civil de Catalunya (art. 16.1), i integra els plans territorials i especials (art. 16.2).","refs":[{"ref":"Art. 15.1 i 16.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los planes de protección civil pueden ser territoriales, especiales y de autoprotección. […] El Plan de protección civil de Cataluña debe ser aprobado por el Gobierno a propuesta del Consejero o Consejera de Gobernación, previo informe de la Comisión de Protección Civil de Cataluña."}]},{"text":"Els plans territorials preveuen amb caràcter general les emergències d''un àmbit; els nivells bàsics són Catalunya i els municipis (art. 17.1). Han d''elaborar un pla bàsic d''emergència municipal els municipis de més de vint mil habitants i els turístics o de risc especial; l''aprova el ple i l''homologa la Comissió de Protecció Civil de Catalunya (art. 17.2).","refs":[{"ref":"Art. 17.2 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los municipios con una población superior a los veinte mil habitantes y los que, sin alcanzar esta población, tienen la consideración de turísticos o los considerados de riesgo especial"}]},{"text":"Els plans especials tracten emergències generades per riscos concrets que requereixen mètodes tècnics i científics específics: inundacions, sismes, accidents químics, transport de mercaderies perilloses, incendis forestals, volcans i els que determini el Govern; es declaren d''interès de Catalunya i els aprova el Govern (art. 18).","refs":[{"ref":"Art. 18.1 i 18.2 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los planes especiales establecen las emergencias generadas por riesgos concretos cuya naturaleza requiere unos métodos técnicos y científicos adecuados para su evaluación y tratamiento. […] Los planes especiales se declaran de interés de Cataluña."}]},{"text":"Els plans d''autoprotecció preveuen, per a determinats centres, empreses i instal·lacions, les emergències derivades de la pròpia activitat i les respostes davant riscos que els poden afectar; els homologa sempre la Comissió de Protecció Civil de Catalunya, amb informe favorable de l''ajuntament (art. 19).","refs":[{"ref":"Art. 19.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los planes de autoprotección prevén, para determinados centros, empresas e instalaciones, las emergencias que pueden producirse como consecuencia de su propia actividad"}]},{"text":"Tots els plans tenen un contingut homogeni (art. 20): entre altres, el comitè d''emergència (director del pla, consell assessor i gabinet d''informació), uns serveis operatius organitzats com a mínim en grups d''intervenció, d''ordre, sanitari i logístic, i unes infraestructures amb un centre receptor d''alarmes, un centre de coordinació operativa i centres de comandament avançat. Els plans s''han de revisar cada quatre anys (art. 24.2). El director del pla en declara formalment l''activació, que comporta, entre altres, comunicar-la al CECAT (art. 27).","refs":[{"ref":"Art. 20.1.e i 24.2 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los servicios operativos, que se organizan, como mínimo, en los grupos de intervención, de orden, sanitario y logístico […] Todos los planes deben ser revisados cada cuatro años."}]}]},{"n":"12","title":"Estructura: autoritats, Govern, CECAT, Comissió de Protecció Civil i municipis","blocks":[{"text":"L''estructura de la protecció civil a Catalunya la formen les administracions públiques, els serveis d''autoprotecció i el voluntariat de protecció civil (art. 39). Són autoritats de protecció civil l''alcalde o alcaldessa, en l''àmbit municipal, i el conseller o consellera del departament competent, en l''àmbit de Catalunya; les autoritats són els directors dels plans del seu àmbit (art. 40).","refs":[{"ref":"Art. 40 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"a) El Alcalde o Alcaldesa, en el ámbito municipal. b) El Consejero o Consejera de Gobernación, en el ámbito de Cataluña"}]},{"text":"El Govern és l''òrgan col·legiat superior de direcció i coordinació de la protecció civil i aprova el Pla de protecció civil de Catalunya, els plans territorials supramunicipals i els especials (art. 42). El conseller o consellera és l''autoritat superior de protecció civil de Catalunya: declara l''activació dels plans d''àmbit català, presideix la Comissió de Protecció Civil i dirigeix el CECAT (art. 43). També li correspon declarar l''emergència d''interès de Catalunya (art. 29.3).","refs":[{"ref":"Art. 42.1 i 43.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"El Gobierno de la Generalidad es el órgano colegiado superior de dirección y coordinación de protección civil de Cataluña. […] El Consejero o Consejera de Gobernación es la autoridad superior de protección civil de Cataluña"}]},{"text":"El Centre de Coordinació Operativa de Catalunya (CECAT) és el centre superior de coordinació i informació de l''estructura de protecció civil de Catalunya; és un òrgan administratiu sense personalitat jurídica pròpia, adscrit al departament (art. 45).","refs":[{"ref":"Art. 45 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"El Centro de Coordinación Operativa de Cataluña (CECAT) es el centro superior de coordinación e información de la estructura de protección civil de Cataluña […] El CECAT es un órgano Administrativo, sin personalidad jurídica propia, adscrito al Departamento de Gobernación."}]},{"text":"La Comissió de Protecció Civil de Catalunya és l''òrgan col·legiat de caràcter consultiu, deliberant, coordinador i homologador superior en la matèria; hi ha representants de la Generalitat, de l''Administració de l''Estat a Catalunya i de l''Administració local, i homologa, entre altres, els plans municipals (art. 46).","refs":[{"ref":"Art. 46.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"La Comisión de Protección Civil de Cataluña es el órgano colegiado de carácter consultivo, deliberante, coordinador y homologador superior en la materia en Cataluña."}]},{"text":"Els municipis són les entitats bàsiques de la protecció civil a Catalunya (art. 47.1); el ple aprova els plans municipals, i l''alcalde és l''autoritat local superior de protecció civil, que activa els plans municipals i ho comunica al conseller mitjançant el CECAT (art. 48). Els ajuntaments obligats a tenir plans han de crear un centre de coordinació operativa municipal (CECOPAL) coordinat amb el CECAT (art. 49), i els municipis de més de cinquanta mil habitants han de crear una Comissió Municipal de Protecció Civil (art. 51.1).","refs":[{"ref":"Art. 47.1 i 49 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los municipios son las entidades básicas de la protección civil en Cataluña […] deben crear y mantener centros de coordinación operativa, en las condiciones que fije por reglamento el Gobierno y, en todo caso, deben actuar en coordinación con el CECAT."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Escala tècnica = oficial, sergent, caporal i bomber de primera (grup C1). Superior = inspector; executiva = sotsinspector; suport = TECOR, TEOV, EPAF i TELOG.","refs":[{"ref":"Art. 15 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"Escala técnica, que comprende las categorías de oficial, de sargento, de cabo y de bombero de primera."}]},{"text":"En acte de servei, els bombers són agents de l''autoritat; fora de servei, si intervenen en un sinistre després d''acreditar-se, també es consideren en acte de servei.","refs":[{"ref":"Art. 10 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"tienen la consideración de agentes de la autoridad […] previa acreditación de su condición."}]},{"text":"Coordinació en emergències: la màxima autoritat és el Cos de Bombers, a través del comandament màxim que intervingui.","refs":[{"ref":"Art. 14.4 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"a través del mando máximo que intervenga"}]},{"text":"Prestacions personals en risc greu: obligatòries i sense indemnització. Requises: amb indemnització.","refs":[{"ref":"Art. 3.2 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"las cuales no dan derecho a indemnización."}]},{"text":"Bomber de primera: oposició o concurs oposició lliure + curs selectiu a l''Escola. Des de l''escala de suport no hi ha promoció interna a altres escales.","refs":[{"ref":"Art. 18.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"El acceso a la categoría de bombero de primera se realiza por oposición o por concurso-oposición, en convocatoria libre."}]},{"text":"Més de 20.000 habitants: la prevenció i extinció d''incendis és servei mínim obligatori del municipi. L''habilitació de bomber d''empresa l''expedeix l''Escola de Bombers.","refs":[{"ref":"Art. 47.1 Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"En los municipios de más de veinte mil habitantes, la prevención y la extinción de incendios constituyen un servicio mínimo"}]},{"text":"Llei 4/1997: plans territorials, especials (riscos concrets: inundacions, incendis forestals, químics…) i d''autoprotecció. El Pla de Catalunya l''aprova el Govern amb informe previ de la Comissió.","refs":[{"ref":"Art. 15.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los planes de protección civil pueden ser territoriales, especiales y de autoprotección."}]},{"text":"Autoritats: alcalde (municipal) i conseller (Catalunya). CECAT = centre superior de coordinació i informació. Comissió = òrgan consultiu, deliberant, coordinador i homologador superior. Municipis = entitats bàsiques.","refs":[{"ref":"Art. 47.1 Llei 4/1997","law":"Llei 4/1997","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409","quote":"Los municipios son las entidades básicas de la protección civil en Cataluña"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665', null, null, null, 'Otras normas citadas: Llei 4/1997 (https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409)'
