insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.009 Manual operatiu bàsic sobre hidràulica i bombes (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
