   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.002 Manual operatiu bàsic de cartografia i orientació (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t14-cartografia-orientacio', 'Tema 14. Cartografia i orientació') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t14-cartografia-orientacio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Coordenades geogràfiques: paral·lels, meridians, latitud i longitud"},{"n":"2","title":"Sistema UTM: fusos, zones i coordenades X/Y; Catalunya a la zona 31T"},{"n":"3","title":"Datum: ED50, WGS84 i ETRS89"},{"n":"4","title":"Escales numèrica i gràfica"},{"n":"5","title":"Relleu: corbes de nivell, corbes mestres i equidistància"},{"n":"6","title":"Orientació amb brúixola: Nord magnètic, declinació i azimut"},{"n":"7","title":"GNSS: segments i fonts d''error"},{"n":"8","title":"Cartografia Operativa d''Emergències (COE)"}]'::jsonb, '["§ latitud MAN.GRAL.002: «S''utilitzen per a mesurar la latitud, que és l''angle d''un punt respecte a l''equador.»","§ UTM MAN.GRAL.002: «Coordenades UTM En la dècada de 1940, l’exèrcit dels EUA va definir el sistema de coordenades UTM (Universal Transverse Mercator), que com el seu nom indica es basa en la projecció cartogràfica transversa de Mercator.»","§ fusos MAN.GRAL.002: «En total, la superfície de la terra es va segmentar en 60 porcions de la terra (de 6º cada una), numerades de l’1 al 60, que s’anomenen fusos.»","§ datum MAN.GRAL.002: «Històricament, cada país o servei cartogràfic feia servir el seu, com l’ED50 a Espanya i Europa, mentre que la navegació per satèl·lit i àmbits internacionals utilitzaven el WGS84.»","§ diferència de datums MAN.GRAL.002: «La diferència entre aquests dos sistemes (fins a 200 m) provocava desajustos entre mapes i GPS.»","§ escala MAN.GRAL.002: «Això vol dir que 1 unitat de mesura al mapa (1 cm, 1 mm, etc.) equival a 25.000 de la mateixa unitat al terreny.»","§ equidistància i escala MAN.GRAL.002: «La equidistància està relacionada amb l’escala del mapa, per no sobrecarregar-lo de corbes i fer- lo il·legible.»","§ GNSS MAN.GRAL.002: «Un Global Navigation Satellite System (GNSS) és un sistema que utilitza satèl·lits per determinar la posició geogràfica, altitud i velocitat d''un receptor a la superfície de la Terra.»","§ errors atmosfèrics MAN.GRAL.002: «Els senyals de ràdio es veuen afectats en travessar la ionosfera i la troposfera.»","§ COE MAN.GRAL.002: «El Cos de Bombers de la Generalitat de Catalunya ha desplegat la seva pròpia cartografia, anomenada Cartografia Operativa d''Emergències (COE), que permet l’aproximació, l’anàlisi i el treball durant l’emergència, així com l’inventari d’infraestructures d’extinció d’incendis com són els camins forestals i els punts d’aigua.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La cartografia i les projeccions cartogràfiques","blocks":[{"text":"La cartografia és la ciència que s''ocupa de la representació gràfica de la superfície de la Terra. Un mapa no és la realitat, sinó un model on el cartògraf selecciona i prioritza la informació segons la finalitat del document. Per representar la Terra esfèrica en un pla s''utilitzen projeccions: com si una bombeta al centre de la Terra projectés la superfície sobre una pantalla; segons la forma i posició de la «pantalla» hi ha diferents projeccions, cadascuna amb les seves distorsions.","refs":[{"ref":"MAN.GRAL.002, 2 La cartografia","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"La cartografia és la ciència que s''ocupa de la representació gràfica de la superfície de la Terra o de parts d''aquesta."},{"ref":"MAN.GRAL.002, 2.1 Projeccions","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Segons la forma i posició d''aquesta \"pantalla\" on es projecta, obtenim diferents tipus de projeccions, cadascuna amb les seves pròpies característiques i distorsions."}]},{"text":"Al segle XVI Gerardus Mercator va proposar la projecció cilíndrica normal, pensada per a la navegació oceànica; el seu inconvenient és la gran distorsió lluny de l''equador. La projecció transversal de Mercator fa servir diversos cilindres amb l''eix horitzontal, i cada un només projecta la porció que millor hi coincideix, cosa que minimitza les distorsions.","refs":[{"ref":"MAN.GRAL.002, 2.1 Projeccions","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Al segle XVI, el geògraf i cartògraf Gerardus Mercator va proposar la projecció cilíndrica normal, pensada per la navegació oceànica."},{"ref":"MAN.GRAL.002, 2.1 Projeccions","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"de manera que en cada cilindre només s’hi projecta una porció de la superfície de la terra, la que millor coincideix amb aquell cilindre. Així es minimitzen les distorsions."}]}]},{"n":"2","title":"Sistemes de coordenades: coordenades geogràfiques","blocks":[{"text":"Les coordenades geogràfiques es basen en una graella de meridians i paral·lels. Els paral·lels són cercles paral·lels a l''equador i serveixen per mesurar la latitud (angle d''un punt respecte a l''equador). Els meridians uneixen el pol Nord amb el pol Sud, són perpendiculars als paral·lels i mesuren la longitud (angle respecte al meridià de Greenwich, el meridià 0).","refs":[{"ref":"MAN.GRAL.002, 2.2.1 Coordenades geogràfiques","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Els paral·lels són cercles concèntrics i paral·lels a l''equador. S''utilitzen per a mesurar la latitud, que és l''angle d''un punt respecte a l''equador."},{"ref":"MAN.GRAL.002, 2.2.1 Coordenades geogràfiques","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Els meridians són línies que uneixen el pol Nord amb el pol Sud i que són perpendiculars als paral·lels. S''utilitzen per a mesurar la longitud, que és l''angle d''un punt respecte al Meridià de Greenwich (el meridià 0)."}]},{"text":"S''expressen en graus decimals o en graus, minuts i segons; cobreixen tota la Terra i les fan servir la navegació aèria i marítima, els mapes d''internet i, per defecte, els aparells GPS. En mapes terrestres són poc pràctiques: poc intuïtives i amb càlculs de distància complexos.","refs":[{"ref":"MAN.GRAL.002, 2.2.1 Coordenades geogràfiques","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"No obstant això, la seva representació en mapes terrestres és poc pràctica."}]}]},{"n":"3","title":"Coordenades UTM","blocks":[{"text":"El sistema UTM (Universal Transverse Mercator) el va definir l''exèrcit dels EUA als anys quaranta i es basa en la projecció transversa de Mercator. La Terra es divideix en 60 fusos de 6°, numerats de l''1 al 60; cada fus, en 20 trossos (zones) identificats amb lletres de la C a la X des del sud (sense la I ni la O); a partir de la N són de l''hemisferi nord.","refs":[{"ref":"MAN.GRAL.002, 2.2.2 Coordenades UTM","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"En total, la superfície de la terra es va segmentar en 60 porcions de la terra (de 6º cada una), numerades de l’1 al 60, que s’anomenen fusos."}]},{"text":"La X mesura la distància al meridià central del fus (direcció est-oest), al qual s''assigna X = 500.000 m per evitar valors negatius. La Y mesura la distància a l''equador (a l''hemisferi nord, Y = 0 a l''equador). Tot Catalunya és a la zona 31T i normalment no cal indicar-la; a la resta de la Península hi ha tres fusos (29, 30 i 31). A Catalunya la X té 6 xifres i la Y, 7. Com que és una quadrícula en metres, les distàncies es calculen fàcilment (Pitàgores).","refs":[{"ref":"MAN.GRAL.002, 2.2.2 Coordenades UTM","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Al meridià central del fus se li assigna la coordenada X=500.000 m (per tal de no tenir valors de X negatius, i facilitar els càlculs)."},{"ref":"MAN.GRAL.002, 2.2.2 Coordenades UTM","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"A Catalunya això és més senzill perquè tot el territori es troba dins la zona 31T, i per tant normalment no cal especificar-la, mentre que a la resta de la Península Ibèrica sí, ja que hi ha tres fusos diferents (29, 30 i 31)."},{"ref":"MAN.GRAL.002, 2.2.2 Coordenades UTM","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"A més, les coordenades UTM a Catalunya tenen sempre 6 xifres per a la X i 7 per a la Y"}]}]},{"n":"4","title":"El datum","blocks":[{"text":"El datum és el sistema de referència que defineix la posició i orientació d''un sistema de coordenades: una mateixa coordenada pot situar punts diferents segons el datum. Històricament s''usava l''ED50 a Espanya i Europa i el WGS84 en navegació per satèl·lit; la diferència, de fins a 200 m, provocava desajustos entre mapes i GPS. La UE va adoptar l''ETRS89, gairebé idèntic al WGS84, avui oficial a Europa, tot i que encara circulen mapes antics amb altres datums.","refs":[{"ref":"MAN.GRAL.002, 2.2.3 El Datum","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"El datum és el sistema de referència que defineix la posició i orientació d’un sistema de coordenades."},{"ref":"MAN.GRAL.002, 2.2.3 El Datum","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"La diferència entre aquests dos sistemes (fins a 200 m) provocava desajustos entre mapes i GPS. Per unificar criteris, la UE va adoptar el ETRS89 (1989), gairebé idèntic al WGS84, que avui és el sistema oficial a Europa"}]}]},{"n":"5","title":"Mapes: tipus i elements cartogràfics","blocks":[{"text":"El mapa topogràfic és el que s''usa per orientar-se: hi ha el relleu, elements naturals, infraestructures, límits administratius i toponímia. Segons el suport, n''hi ha d''impresos (no necessiten energia, però no es poden actualitzar) i digitals; aquests poden ser ràster (imatge, es pixel·len amb el zoom; les ortofotos en són un tipus) o vectorials (punts, línies, polígons i text, no es pixel·len), i online o offline.","refs":[{"ref":"MAN.GRAL.002, 2.3.1 Tipus de mapes","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Mapes vectorials: Representen la informació mitjançant entitats geomètriques (punts, línies, polígons i text)."}]},{"text":"Els elements del mapa poden ser puntuals (cims, pous), lineals (rius, camins), àrees (llacs, boscos) i text (topònims). La llegenda és la clau per entendre el mapa. L''ombrejat simula una llum, generalment del nord-oest, per donar sensació de relleu; la seva orientació és arbitrària.","refs":[{"ref":"MAN.GRAL.002, 2.3.4 Elements del mapa","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"La llegenda és la clau per entendre el mapa, ja que explica com es representa cada element"},{"ref":"MAN.GRAL.002, 2.3.5 L''ombrejat","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Consisteix en enfosquir àrees del mapa com si el terreny estigués il·luminat per una font de llum, generalment provinent del nord-oest"}]}]},{"n":"6","title":"Escales","blocks":[{"text":"L''escala és la proporció constant entre una distància al mapa i la real al terreny. L''escala numèrica és una fracció: en 1:25.000, 1 unitat al mapa equival a 25.000 de la mateixa unitat al terreny (1 cm = 250 m). Una escala gran és un mapa reduït poques vegades: molt detall i poca superfície; l''1:10.000 és més gran que l''1:50.000.","refs":[{"ref":"MAN.GRAL.002, 2.3.2 Escala numèrica","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Això vol dir que 1 unitat de mesura al mapa (1 cm, 1 mm, etc.) equival a 25.000 de la mateixa unitat al terreny. Per exemple, 1 cm al mapa representa 25.000 cm (o 250 metres) al terreny."},{"ref":"MAN.GRAL.002, 2.3.2 Escala gran","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Per exemple, un mapa a escala 1:10.000 està a escala més gran que un 1:50.000."}]},{"text":"L''escala gràfica és una línia dividida en segments; el seu gran avantatge és que es redimensiona amb el mapa si s''amplia o es redueix (fotocòpia, mapa digital). En els mapes digitals l''escala numèrica té poc sentit i es parla de nivells de zoom.","refs":[{"ref":"MAN.GRAL.002, 2.3.2 Escala gràfica","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"El gran avantatge de l''escala gràfica és que si el mapa s''amplia o es redueix (per exemple, en una fotocòpia, un mapa digital), l''escala gràfica es redimensiona amb ell, mantenint la seva relació amb la realitat."}]}]},{"n":"7","title":"Corbes de nivell","blocks":[{"text":"Les corbes de nivell o isohipses connecten els punts del terreny amb la mateixa cota o altitud sobre el nivell del mar. La separació vertical entre corbes és l''equidistància, que ha de venir indicada al mapa i depèn de l''escala. Solen ser fines i marrons; generalment cada 5 n''hi ha una de més gruixuda, la corba mestra. En zones planes es poden afegir corbes auxiliars discontínues.","refs":[{"ref":"MAN.GRAL.002, 2.3.3 Corbes de nivell","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Les corbes de nivell (o isohipses) són les línies imaginaries que connecten tots els punts de la superfície del terreny que tenen la mateixa cota o altitud sobre el nivell del mar."},{"ref":"MAN.GRAL.002, 2.3.3 Equidistància","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"La separació vertical entre els talls de les llesques s''anomena equidistància, i ha de venir indicada en el mapa"},{"ref":"MAN.GRAL.002, 2.3.3 Corba mestra","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Cada cert numero de corbes (generalment cada 5 corbes) es dibuixa la corba amb un traç més gruixut, és l’anomenada corba mestra"}]},{"text":"Interpretació: corbes juntes, pendent fort; separades, pendent suau. Les corbes tancades sobre si mateixes solen ser turons. Els cursos d''aigua naturals creuen les corbes perpendicularment. Un camí paral·lel a les corbes és pla.","refs":[{"ref":"MAN.GRAL.002, 2.3.3 Interpretació","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Allí on les línies estan molt juntes el pendent és pronunciat"},{"ref":"MAN.GRAL.002, 2.3.3 Interpretació","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Els cursos d’aigua naturals creuen les corbes de nivell perpendicularment ja que l’aigua segueix la línia de màxim pendent"}]}]},{"n":"8","title":"Orientació: orientar el mapa i ús de la brúixola","blocks":[{"text":"Orientar-se és saber on som i com arribar a un altre punt. Les eines són el mapa, la brúixola, el GPS, els mapes digitals i els navegadors. Cal tenir el mapa orientat, amb el nord del mapa cap al nord real. Sense brúixola es pot orientar amb referències del terreny (un turó, la carretera, un edifici).","refs":[{"ref":"MAN.GRAL.002, 3.1 Orientar el mapa","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Un principi fonamental per orientar-se amb un mapa és tenir-lo ben orientat. És a dir, que l’orientació del mapa es correspongui amb el terreny."}]},{"text":"La brúixola indica el Nord magnètic amb una agulla imantada; per al mapa són millors les planes i transparents, amb limbe giratori. Per orientar el mapa: posar-lo horitzontal, apuntar la fletxa de la brúixola al nord del mapa i girar tots dos fins que l''agulla s''alineï. El Nord magnètic difereix del geogràfic una mica (menys de 2°), varia amb el lloc i els anys i ha d''estar indicat al mapa. Cal mantenir la brúixola horitzontal i lluny de metalls i camps magnètics.","refs":[{"ref":"MAN.GRAL.002, 3.1.1 La brúixola","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"La brúixola és un instrument que ens indica el Nord magnètic."},{"ref":"MAN.GRAL.002, 3.1.1 La brúixola","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Tinguem en compte que el Nord magnètic no coincideix exactament amb el Nord geogràfic, hi ha una petita desviació que varia amb el lloc i amb els anys, per això ha de venir indicada en el mapa. No obstant és molt petita (no arriba als 2º)"},{"ref":"MAN.GRAL.002, 3.1.1 La brúixola","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"És important mantenir la horitzontalitat de la brúixola."}]},{"text":"La direcció es defineix amb l''azimut, angle respecte al nord. Per localitzar un punt (una columna de fum) es fa la triangulació: almenys dos observadors en posició coneguda prenen l''azimut i l''objectiu és on es creuen les visuals.","refs":[{"ref":"MAN.GRAL.002, 3.1.1 Azimut","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"La direcció es defineix mitjançant l''azimut, que és l''angle respecte al nord."},{"ref":"MAN.GRAL.002, 3.1.1 Triangulació","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Amb un mínim de dos observadors es pot triangular, però com més observadors hi participin, més precís serà el resultat."}]}]},{"n":"9","title":"Sistemes d''orientació natural","blocks":[{"text":"Sol: l''hora solar és l''oficial menys 2 h a l''estiu i menys 1 h a l''hivern. A les 12 h solars el sol és exactament al sud (l''ombra d''una estaca apunta al nord). Només surt exactament per l''est als equinoccis. Amb un rellotge de manetes en hora solar, la bisectriu entre l''agulla de les hores (apuntant al sol) i el 12 indica el sud. L''estrella Polar assenyala el nord geogràfic (es troba amb l''Ossa Major o Cassiopea). Referències aproximades: molsa i anells dels arbres (nord), altars d''esglésies (est), plaques solars (sud).","refs":[{"ref":"MAN.GRAL.002, 3.2.1 Orientació pel sol","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"El que es compleix sempre, és que a les 12:00 h del migdia hora solar, el sol es troba exactament a sobre del punt cardinal sud."},{"ref":"MAN.GRAL.002, 3.2.3 Estrella Polar","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Només una estrella resta fixa en un punt sense moure''s: l''estrella Polar, que assenyala directament cap al nord geogràfic."}]}]},{"n":"10","title":"GNSS i mapes digitals","blocks":[{"text":"Un GNSS determina la posició, l''altitud i la velocitat d''un receptor mitjançant satèl·lits. Té tres segments: espacial (satèl·lits), de control (bases terrestres que ajusten les òrbites i sincronitzen els rellotges atòmics) i d''usuari (receptors). La posició es calcula per trilateració, amb un mínim de quatre satèl·lits per a una posició en 3D.","refs":[{"ref":"MAN.GRAL.002, 4.1 Principis","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Segment de control: una xarxa de bases terrestres que monitoritzen els satèl·lits per ajustar-ne les òrbites i sincronitzar-ne els rellotges atòmics."},{"ref":"MAN.GRAL.002, 4.1 Principis","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"El càlcul de la posició es fa per trilateració (com la triangulació però amb distàncies), a partir del temps que tarda el senyal de ràdio a viatjar des de diversos satèl·lits (un mínim de quatre per a una posició en 3D)"}]},{"text":"Fonts d''error: propagació atmosfèrica (ionosfera i troposfera), geometria dels satèl·lits, ocultació, rebots o efecte multicamí (el senyal rebota en edificis o roques i el receptor calcula una distància més gran), errors del receptor o datum incorrecte, i degradació intencionada.","refs":[{"ref":"MAN.GRAL.002, 4.2 Fonts d''error","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Rebots (efecte multicamí): Els senyals reboten en superfícies properes (edificis, parets de roca...), de manera que el senyal arriba per camins més llargs."}]},{"text":"Sistemes: GPS (EUA), GLONASS (Rússia), Galileo (UE, d''ús principalment civil), BeiDou (Xina), QZSS (Japó) i NavIC (Índia). Receptors: GPS dedicats, rellotges, mòbils, navegadors i drons. El senyal GNSS no depèn de la cobertura mòbil. Funcions: posició, waypoints, velocitat, gravació del track i navegació.","refs":[{"ref":"MAN.GRAL.002, 4.3 Sistemes existents","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Galileo: El sistema de la Unió Europea, dissenyat principalment per a ús civil i amb cobertura global."},{"ref":"MAN.GRAL.002, 4.4.1 Dispositius","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Cal recordar que el senyal GNSS és independent de la cobertura mòbil"}]}]},{"n":"11","title":"Cartografia operativa d''emergències (COE)","blocks":[{"text":"La COE és la cartografia pròpia de Bombers de la Generalitat per a l''aproximació, l''anàlisi i el treball en emergències i per inventariar camins forestals i punts d''aigua. Característiques: tot Catalunya, escala 1:25.000, equidistància 10 m, coordenades UTM i geogràfiques, datum ETRS89 i codi SOC. Es desplega sobre la base cartogràfica de l''Institut Cartogràfic i Geològic de Catalunya (ICGC).","refs":[{"ref":"MAN.GRAL.002, 5 COE","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Cobertura de tot el territori de Catalunya − Escala 1:25.000 − Equidistància 10 m − Doble sistema de coordenades: UTM i geogràfiques − Datum ETRS89"},{"ref":"MAN.GRAL.002, 5.1 Base cartogràfica","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"La COE es desplega a partir de la base cartogràfica de l’Institut Cartogràfic i Geològic de Catalunya (ICGC)"}]},{"text":"Camins: primaris (s''hi creuen dos vehicles pesats, mínim 6 m, línia groga), secundaris (sobreamples cada 100-150 m, 3-5 m d''amplada), terciaris (no s''hi creuen, mínim 3 m) i no accessibles a BRP. Els PAIF són punts d''aigua de més de 200 m³ accessibles per helicòpters i mitjans terrestres. Un hidrant amb aspa fa temps que no s''ha revisat.","refs":[{"ref":"MAN.GRAL.002, 5.2.1 Xarxa de camins","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"És a dir, tenen una amplada mínima de 6 m. Es representa amb una línia groga contínua."},{"ref":"MAN.GRAL.002, 5.2.2 Punts d''aigua","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Una capacitat superior als 200 metres cúbics"}]},{"text":"Els mapes de la COE porten el codi del Mapa Topogràfic Nacional 1:25.000 (full 1:50.000 de 3 xifres dividit en 4: p. ex. 522-1). El codi SOC (Sistema d''Orientació Cartogràfica) usa la quadrícula UTM: quadrant de 5 × 5 km (dos números i dues lletres) i 25 seccions d''1 × 1 km (p. ex. 22AP06).","refs":[{"ref":"MAN.GRAL.002, 5.3.2 Codi SOC","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"El quadrant identifica un reticle de 5×5 km i utilitza una combinació de dos números i dues lletres."}]}]},{"n":"12","title":"Sistemes d''informació geogràfica (SIG)","blocks":[{"text":"Els SIG recullen, emmagatzemen, analitzen i representen informació geogràfica. Permeten triar mapes base i treballar amb capes temàtiques que s''activen o desactiven i es mostren a partir d''un cert zoom. Inclouen elements puntuals amb atributs (hidrants, túnels), edició compartida d''elements gràfics (maniobres, accessos, zones d''evacuació) i eines com el seguiment en temps real d''unitats, el rastre o la conversió de coordenades. El manual adverteix que poden generar una elevada dependència del sistema.","refs":[{"ref":"MAN.GRAL.002, 6 SIG","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Els SIG són eines informàtiques que permeten recollir, emmagatzemar, analitzar i representar informació geogràfica."},{"ref":"MAN.GRAL.002, 6.2 Capes","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Les capes poden activar-se o desactivar-se segons les necessitats de l’usuari"},{"ref":"MAN.GRAL.002, 6 SIG","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Aquesta disponibilitat constant de dades pot generar, però, una elevada dependència del sistema."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Latitud: angle respecte a l''equador. Longitud: respecte a Greenwich. Meridians: de pol a pol, perpendiculars als paral·lels.","refs":[{"ref":"MAN.GRAL.002, 2.2.1","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"la latitud, que és l''angle d''un punt respecte a l''equador"}]},{"text":"UTM: 60 fusos de 6°; X = 500.000 m al meridià central; Catalunya, zona 31T (X de 6 xifres, Y de 7).","refs":[{"ref":"MAN.GRAL.002, 2.2.2","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"tot el territori es troba dins la zona 31T"}]},{"text":"Datum oficial europeu: ETRS89 (≈ WGS84). ED50-WGS84: fins a 200 m.","refs":[{"ref":"MAN.GRAL.002, 2.2.3","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"gairebé idèntic al WGS84"}]},{"text":"1:25.000 → 1 cm = 250 m. 1:10.000 és més gran que 1:50.000. L''escala gràfica es redimensiona amb el mapa.","refs":[{"ref":"MAN.GRAL.002, 2.3.2","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"1 cm al mapa representa 25.000 cm (o 250 metres) al terreny"}]},{"text":"Isohipses: mateixa altitud. Corba mestra: cada 5. Equidistància: separació vertical, indicada al mapa.","refs":[{"ref":"MAN.GRAL.002, 2.3.3","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"és l’anomenada corba mestra"}]},{"text":"Brúixola: Nord magnètic (diferència amb el geogràfic < 2°, variable). Horitzontal i lluny de metalls. Azimut: angle respecte al nord.","refs":[{"ref":"MAN.GRAL.002, 3.1.1","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"La direcció es defineix mitjançant l''azimut, que és l''angle respecte al nord."}]},{"text":"GNSS: segment de control = bases terrestres. Error per rebots: efecte multicamí. Mínim 4 satèl·lits per a 3D.","refs":[{"ref":"MAN.GRAL.002, 4.2","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Rebots (efecte multicamí)"}]},{"text":"COE: base ICGC, 1:25.000, equidistància 10 m, ETRS89, codi SOC (quadrant 5 × 5 km, secció 1 × 1 km).","refs":[{"ref":"MAN.GRAL.002, 5 COE","law":"MAN.GRAL.002","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf","quote":"Equidistància 10 m"}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf', null, null, null, null
