insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Impacte global de les inundacions i episodis a Catalunya"},{"n":"2","title":"Factors que afavoreixen les inundacions i canvi climàtic"},{"n":"3","title":"GRAE Subaquàtic"},{"n":"4","title":"Morfologia fluvial i tipus de cursos d''aigua"},{"n":"5","title":"Tipus d''inundacions i avingudes sobtades"},{"n":"6","title":"Zones inundables i període de retorn"},{"n":"7","title":"Valoració del risc: avisos, mapes i saturació del sòl"},{"n":"8","title":"Maniobres: buidatge, contenció, potabilització, recerca i rescat"}]'::jsonb, '["§ amenaça global MAN.SVMN.001: «Aquestes dades mostren que les inundacions no són només un problema local, sinó una amenaça global creixent, especialment en un context de canvi climàtic, urbanització accelerada i fragilitat dels ecosistemes.»","§ context mediterrani MAN.SVMN.001: «En el context mediterrani, amb pluges irregulars però molt intenses, aquests factors potencien encara més la vulnerabilitat del territori.»","§ capçalera MAN.SVMN.001: «Aquestes crescudes tenen una elevada capacitat d’arrossegament (pedres, fang, troncs) i el cabal pot augmentar en qüestió de minuts, amb risc d’avingudes fulminants.»","§ predicció MAN.SVMN.001: «El període de retorn no és una predicció, sinó una manera d’avaluar el risc.»","§ valoració MAN.SVMN.001: «Valoració del risc en inundacions Per garantir una intervenció eficaç i segura davant d’un episodi d’inundacions, cal fer una valoració prèvia acurada del risc i de l’escenari.»","§ potabilització MAN.SVMN.001: «Potabilització d’aigua En situacions d’emergència, quan l’aigua ha quedat contaminada o el subministrament habitual s’ha interromput, és essencial garantir aigua potable per a la població i per als serveis bàsics.»","§ rescat MAN.SVMN.001: «Maniobres de recerca i rescat en zones inundades El rescat de persones atrapades per una inundació és una de les actuacions més exigents i delicades per part dels cossos operatius.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Riscos naturals i impacte global de les inundacions","blocks":[{"text":"Els riscos naturals formen part del funcionament normal de la natura, però quan interactuen amb zones habitades poden desencadenar desastres. Les inundacions són, amb diferència, el risc que més afectacions genera al món, en víctimes i en danys materials. A Catalunya són el risc natural més freqüent i potencialment més greu, sobretot en episodis de pluja intensa de curta durada (rissagues, pluges torrencials, gotes fredes).","refs":[{"ref":"MAN.SVMN.001, § 1.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Entre tots els fenòmens naturals, les inundacions destaquen per ser, amb diferència, el risc que més afectacions genera al món, tant en nombre de víctimes com en danys materials."},{"ref":"MAN.SVMN.001, § 1.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"A Catalunya, les inundacions són el risc natural més freqüent i potencialment més greu, especialment en episodis de pluja intensa de curta durada (rissagues, pluges torrencials, gotes fredes...)"}]},{"text":"Les emergències per inundacions representen més del 40 % de tots els desastres naturals registrats cada any al món, amb pèrdues multimilionàries i conseqüències humanitàries (morts, desplaçaments, aigües contaminades). També afecten regions desenvolupades com l''Europa Occidental.","refs":[{"ref":"MAN.SVMN.001, § 1.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Es calcula que les emergències derivades de les inundacions representen més del 40% de tots els desastres naturals registrats anualment a escala global."}]},{"text":"A Catalunya hi ha hagut episodis greus: la riuada del Vallès Occidental de 1962 (gairebé 1.000 morts), les del Bages i el Baix Llobregat de 1971 (21 morts), la de Tarragona de 1994 i les de les Terres de l''Ebre del 2018, 2021 i 2023. El relleu abrupte i una xarxa hidrogràfica curta i intensa afavoreixen respostes sobtades i violentes de l''aigua.","refs":[{"ref":"MAN.SVMN.001, § 1.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"A Catalunya s’han registrat episodis greus com la riuada del Vallès Occidental de 1962 (amb gairebé 1000 persones mortes), les del Bages i Baix Llobregat l’any 1971 (amb 21 persones mortes), la de Tarragona l’any 1994, o les més recents a les Terres de l’Ebre els anys 2018, 2021 i 2023."},{"ref":"MAN.SVMN.001, § 1.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El territori presenta un relleu abrupte i una xarxa hidrogràfica curta i intensa, que afavoreix respostes sobtades i violentes de l’aigua."}]}]},{"n":"2","title":"Factors que afavoreixen les inundacions i canvi climàtic","blocks":[{"text":"Hi influeixen el territori i l''activitat humana: creixement urbà desordenat en zones inundables, impermeabilització del sòl i pèrdua de coberta vegetal (menys absorció i més escorrentia), i manca de manteniment de rieres i drenatges. El canvi climàtic fa més freqüents, intensos i imprevisibles els episodis extrems de precipitació, i el període de risc ja no es concentra només a la tardor.","refs":[{"ref":"MAN.SVMN.001, § 1.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El creixement urbà desordenat en zones inundables, la impermeabilització del sòl i la pèrdua de coberta vegetal redueixen la capacitat natural d’absorció i afavoreixen l’escorrentia."},{"ref":"MAN.SVMN.001, § 1.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El canvi climàtic accentua aquesta problemàtica, ja que altera els patrons meteorològics i fa més freqüents, intensos i imprevisibles els episodis extrems de precipitació. A més, el període de risc ja no es concentra només a la tardor, sinó que s’estén a altres moments de l’any."}]}]},{"n":"3","title":"Mesures de reducció del risc, rol dels serveis d''emergència i GRAE Subaquàtic","blocks":[{"text":"Mesures estructurals: obres que modifiquen el comportament de l''aigua (dics, murs, basses de laminació, clavegueram pluvial, reforç de ponts, comportes, elevació de carreteres); són cares i requereixen manteniment. Mesures no estructurals: cartografia de zones inundables i regulació urbanística (l''acció més important per reduir el risc), gestió de conques, alerta primerenca, plans d''emergència i simulacres i educació; tenen un cost menor.","refs":[{"ref":"MAN.SVMN.001, § 1.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Cartografia de zones inundables i regulació urbanística, que impedeix construir en zones de risc o estableix condicions específiques per fer-ho. És l’acció més important a nivell de reducció del risc."},{"ref":"MAN.SVMN.001, § 1.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Dics, murs de contenció i basses de laminació, que serveixen per frenar o emmagatzemar l’aigua de forma temporal."}]},{"text":"Els Bombers intervenen sobretot quan les mesures preventives han estat superades: preparar-se, intervenir (rescat, esgotament, contenció i suport), coordinar-se (Protecció Civil, ACA, CME, SEM) i recuperar. La Llei 5/1994 atribueix als Bombers el salvament fluvial.","refs":[{"ref":"MAN.SVMN.001, § 1.5","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Els cossos de Bombers i d’emergència s’integren dins d’aquest sistema global de gestió del risc, però intervenen principalment quan les mesures preventives han estat superades i ja s’ha produït l’emergència."},{"ref":"Art. 13.f) Llei 5/1994","law":"Llei 5/1994","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1994-12665","quote":"f) Intervenir en el salvamento fluvial y en el rescate y el salvamento de montaña."}]},{"text":"El GRAE Subaquàtic és l''especialitat dels Bombers per al medi aquàtic i subaquàtic: aigües vives, aigües obertes, trencants, espais confinats inundats, pous i navegació. Disposa d''embarcacions, RAFTs, propulsors, ROVs i material de busseig professional, i la seva activació des dels primers moments pot ser determinant.","refs":[{"ref":"MAN.SVMN.001, § 1.6","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El Grup de Recolzament d’Actuacions Especials (GRAE) Subaquàtic és l’especialitat del Cos de Bombers de la Generalitat de Catalunya dedicada a les intervencions en medi aquàtic i subaquàtic."},{"ref":"MAN.SVMN.001, § 1.6","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"disposa de material específic com embarcacions, RAFTs, propulsors, ROVs, material de busseig professional i sistemes d’estabilització avançats."}]}]},{"n":"4","title":"Medi aquàtic: morfologia i classificació de rius","blocks":[{"text":"Trams: alt o capçalera (fort pendent, gran velocitat, gran arrossegament; el cabal pot augmentar en minuts), mitjà (meandres; risc de desbordament en rieres urbanitzades) i baix (plana i desembocadura: inundacions extenses i persistents, que poden durar hores o dies). Segons el règim: rius permanents, intermitents (desbordaments sobtats quan es reactiven) i torrents i rieres (risc molt alt de riuades flash). Les rieres urbanes canalitzades poden donar una falsa sensació de seguretat.","refs":[{"ref":"MAN.SVMN.001, § 2.1.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Tram baix (plana i desembocadura): En arribar a la plana o al mar, el pendent és mínim i el flux esdevé lent, de manera que el riu pot ocupar àmplies extensions. Les inundacions aquí són sovint extenses i persistents"},{"ref":"MAN.SVMN.001, § 2.1.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Risc: molt alt de riuades flash (flash floods), especialment en zones urbanes o encaixades. Les rieres urbanes canalitzades poden generar una falsa sensació de seguretat, però en realitat són zones de risc alt quan plou intensament."}]},{"text":"Per què importa a l''examen i a la intervenció: la morfologia (forma i comportament del riu) canvia segons el pendent, la geologia, la vegetació i l''activitat humana, i entendre-la permet preveure on i com es produirà la inundació. Al tram alt, les crescudes arrosseguen pedres, fang i troncs; al tram mitjà, el riu forma meandres i el flux s''alenteix, però el risc creix si els marges són inestables o hi ha ocupació urbana. Els rius permanents poden créixer molt sobretot al tram mitjà i baix; els intermitents només porten aigua en determinades èpoques.","refs":[{"ref":"MAN.SVMN.001, § 2.1.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Aquestes crescudes tenen una elevada capacitat d’arrossegament (pedres, fang, troncs) i el cabal pot augmentar en qüestió de minuts, amb risc d’avingudes fulminants."},{"ref":"MAN.SVMN.001, § 2.1.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Tram mitjà: Amb la pèrdua de pendent, el riu forma meandres i el flux s’alenteix, però encara pot créixer amb intensitat."},{"ref":"MAN.SVMN.001, § 2.1.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Risc: poden créixer molt en episodis de pluja, especialment en el tram mitjà i baix."}]}]},{"n":"5","title":"Parts del riu, punts crítics i tipus d''inundacions","blocks":[{"text":"Parts: llera (canal habitual), marge (zones contigües, s''inunden fàcilment), terrasses fluvials (refugi o barrera), meandre (a la part exterior s''erosiona el marge) i aiguabarreig (confluència: el cabal es pot multiplicar). Ponts, murs o acumulacions de vegetació poden fer de colls d''ampolla.","refs":[{"ref":"MAN.SVMN.001, § 2.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Aiguabarreig: Confluència de dos rius o rieres. Punt crític on el cabal es pot multiplicar."},{"ref":"MAN.SVMN.001, § 2.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Meandre: Corba del riu. A la part exterior s’hi erosiona el marge, i pot col·lapsar."}]},{"text":"Tipus: fluvials (desbordament per pluges intenses o persistents; augment progressiu); per avinguda sobtada o flash floods (rieres, torrents i barrancs; de cabal nul a onada destructiva en minuts; les més perilloses per velocitat, força i falta d''avís); costaneres (temporals, llevantades); urbanes (col·lapse del clavegueram o trencament de la xarxa de distribució).","refs":[{"ref":"MAN.SVMN.001, § 2.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"L’aigua pot passar d’un cabal nul a una onada destructiva en minuts. Són les més perilloses per la seva velocitat, força i falta d’avís previ."}]},{"text":"Les inundacions fluvials són habituals en conques grans i rius principals i poden persistir hores o dies. Les costaneres s''agreugen quan coincideixen amb crescudes fluvials. Les urbanes, tot i ser de menor envergadura, poden afectar greument serveis, mobilitat i seguretat ciutadana.","refs":[{"ref":"MAN.SVMN.001, § 2.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Inundacions urbanes: Causades per col·lapse de la xarxa de clavegueram pluvial, sovint en episodis de pluja intensa, o per trencament a la xarxa de distribució."},{"ref":"MAN.SVMN.001, § 2.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"L’augment del cabal és progressiu, però pot assolir valors molt elevats i persistir durant hores o dies."}]}]},{"n":"6","title":"Zones inundables i període de retorn","blocks":[{"text":"El període de retorn (interval de recurrència) indica cada quants anys, de mitjana, pot passar un episodi d''inundació; no és una predicció, sinó una probabilitat: T10 = 10 % anual, T50 = 2 %, T100 = 1 % (usat en planificació urbanística), T500 = 0,2 %. Zones: inundació freqüent (T10 o T25, risc mitjà-baix), ocasional (T50 o T100, risc significatiu) i excepcional (T500, risc alt en situacions extremes).","refs":[{"ref":"MAN.SVMN.001, § 2.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El període de retorn (també anomenat interval de recurrència) és un concepte estadístic que indica cada quants anys, de mitjana, pot passar un determinat episodi d’inundació."},{"ref":"MAN.SVMN.001, § 2.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"10 anys 10% Inundació freqüent, pot passar en qualsevol moment. 50 anys 2% Episodis importants, però no excepcionals. 100 anys 1% Considerats greus. Utilitzats en planificació urbanística. 500 anys 0,2% Inundacions molt excepcionals, però possibles."},{"ref":"MAN.SVMN.001, § 2.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Zona d’inundació ocasional (T50 o T100): Inundacions considerades importants."}]}]},{"n":"7","title":"Valoració del risc: avisos, eines digitals i factors de risc","blocks":[{"text":"El Servei Meteorològic de Catalunya emet Situacions Meteorològiques de Perill (SMP) per pluja segons la intensitat i l''acumulació, amb una escala de 0 a 6 en colors del verd al vermell. Permeten dimensionar recursos, alertar la població i iniciar actuacions preventives. Eines: mapa interactiu de Protecció Civil (cons de dejecció, zones inundables, passos inundables), aforadors de l''ACA (cabals de les conques internes, embassaments, radar) i SAIH Ebro (sistema automàtic d''informació hidrològica de la conca de l''Ebre).","refs":[{"ref":"MAN.SVMN.001, § 3.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Els avisos es classifiquen segons una escala de perill de 0 a 6, representada en un codi de colors que va del verd al vermell"},{"ref":"MAN.SVMN.001, § 3.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"ja que permeten dimensionar recursos, alertar a la població i iniciar actuacions preventives."},{"ref":"MAN.SVMN.001, § 3.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Mapa SAIH Ebro (Sistema automàtic d’informació hidrològica) de les conques de l’Ebre"}]},{"text":"Factors que agreugen: sòl saturat (tota nova pluja és escorrentia directa), urbanització de la llera o del marge, pèrdua de vegetació (l''aigua corre més ràpid i amb més força), manca de manteniment dels cursos, coincidència amb marees altes (efecte represa) i embotellament de ponts o canalitzacions.","refs":[{"ref":"MAN.SVMN.001, § 3.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Quan el sòl ja està completament saturat, no pot absorbir més aigua, de manera que qualsevol nova precipitació es transforma en escorrentia directa cap als cursos d’aigua."},{"ref":"MAN.SVMN.001, § 3.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"fa que l’aigua corri més ràpidament i amb més força cap als torrents i rius, incrementant el risc d’avingudes sobtades i erosió."}]}]},{"n":"8","title":"Maniobres: buidatge, contenció i potabilització","blocks":[{"text":"Buidatge: autobombes (aigües clares o poc brutes), motobombes (llocs de difícil accés), electrobombes (interiors o espais amb accés elèctric) i bombes especials per a llots i aigües greixoses; cal gestionar el destí de l''aigua extreta. Contenció: dics de sacs terrers (puntuals), gabions modulars (llarga durada), maquinària pesada i barreres temporals inflables o rígides. Potabilització: mòduls que analitzen l''aigua i fan clarificació i desinfecció.","refs":[{"ref":"MAN.SVMN.001, § 4.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Motobombes: útils en llocs de difícil accés. − Electrobombes: útils en interiors o espais amb accés elèctric."},{"ref":"MAN.SVMN.001, § 4.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"els dics de sacs terrers, fàcils de desplegar i útils en contencions puntuals; els gabions modulars, que ofereixen més estabilitat en situacions de llarga durada"},{"ref":"MAN.SVMN.001, § 4.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Clarificació, que elimina partícules en suspensió mitjançant filtració o decantació. − Desinfecció, que redueix el risc sanitari eliminant microorganismes patògens."}]}]},{"n":"9","title":"Recerca i rescat: maniobres indirectes, directes i combinades","blocks":[{"text":"Les maniobres indirectes (sense entrar a l''aigua: bossa de corda, perxa dielèctrica, escala o autoescala, flotadors, elements de fortuna) són les preferents si la víctima està conscient i col·labora. Les directes (natació fins a la víctima, control i remolc) són d''alt risc i exigeixen formació, EPI aquàtic i suport a la vora. Les combinades uneixen contacte i recuperació des de terra: armilla amb la bossa de corda lligada al sistema desembragable (rieres, torrents, canals) o línia de rescat de llarga distància (platges, làmines extenses).","refs":[{"ref":"MAN.SVMN.001, § 4.4.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Són les maniobres preferents en primera instància, sempre que les condicions ho permetin i la víctima estigui conscient i col·laboradora."},{"ref":"MAN.SVMN.001, § 4.4.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Aquestes maniobres són considerades d’alt risc i només s’han de fer si: − El rescatador disposa de formació/entrenament específic. − Hi ha EPI aquàtic adequat. − Hi ha personal de suport a la vora amb capacitat de recuperar el rescatador."},{"ref":"MAN.SVMN.001, § 4.4.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El rescatador entra a l’aigua amb l’extrem de la bossa de corda lligat al sistema desembragable de l’armilla."}]},{"text":"Com es tria la maniobra: segons el tipus de zona (urbana, rural, pantanosa, torrent), la profunditat i la força del corrent, la visibilitat i l''accessibilitat, el temps transcorregut des de l''avís i el nombre i l''estat de les persones desaparegudes. Les maniobres es classifiquen pel grau d''exposició del rescatador. Les indirectes són ràpides, segures i fàcils, però no funcionen si la víctima no pot col·laborar; les combinades són especialment indicades quan el rescatador pot ser arrossegat o perdre flotabilitat, l''escenari és gran o el temps de contacte és limitat.","refs":[{"ref":"MAN.SVMN.001, § 4.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El tipus de zona (urbana, rural, pantanosa, torrent, etc.). − La profunditat i força del corrent. − La visibilitat i l’accessibilitat. − El temps transcorregut des de l’avís. − El nombre i condició de les persones desaparegudes."},{"ref":"MAN.SVMN.001, § 4.4.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Avantatges: ràpides, segures i de fàcil execució. Limitacions: no són efectives si la víctima no pot col·laborar."},{"ref":"MAN.SVMN.001, § 4.4.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Hi ha risc que el rescatador sigui arrossegat o perdi flotabilitat."}]}]},{"n":"10","title":"Recerca a peu, embarcacions, canins, helicòpter, subaquàtica, valoració estructural i suport","blocks":[{"text":"Recerca a peu per la riba: extensiva (ràpida, depèn de la resposta de la víctima) o intensiva (lenta, quan la víctima no pot respondre; amb pals o sondes). Embarcacions sense motor (zones pantanoses, poc calat) o amb motor (mai amb víctimes submergides a prop). Unitats canines: localitzen víctimes vives o sense vida en superfície o parcialment submergides. Helicòpter i drons: recerca ràpida a gran escala.","refs":[{"ref":"MAN.SVMN.001, § 4.5","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Indicat quan hi ha sospita que la víctima no pot respondre activament o està parcialment oculta."},{"ref":"MAN.SVMN.001, § 4.6","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"mai operar amb motor en presència de víctimes submergides properes."},{"ref":"MAN.SVMN.001, § 4.7","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Els gossos especialitzats poden localitzar víctimes vives o sense vida en superfície o parcialment submergides, gràcies al seu olfacte."}]},{"text":"L''helicòpter és especialment útil en fases inicials o en zones àmplies o inaccessibles per terra, perquè recorre grans extensions en poc temps i pot intervenir si troba una víctima; els drons capten imatges en directe, segueixen víctimes o avaluen el moviment de l''aigua sense exposar personal. Les embarcacions sense motor són més lentes i exigents físicament i serveixen per a rescats de curta distància.","refs":[{"ref":"MAN.SVMN.001, § 4.8","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"L’helicòpter és especialment útil en fases inicials o en zones àmplies o inaccessibles per terra, ja que pot recórrer grans extensions en poc temps i amb capacitat per intervenir activament en cas de trobar una víctima."},{"ref":"MAN.SVMN.001, § 4.8","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Els drons, com alternativa o complement, ofereixen la capacitat de captar imatges en directe, fer seguiment de víctimes o avaluar el moviment de l’aigua, sense exposar personal operatiu."}]},{"text":"La recerca subaquàtica (bussejadors) és d''alt risc i alt cost i només es fa amb indicis clars de víctima submergida. La valoració estructural la fa la guàrdia GREC (Grup de Recolzament en Estructures Col·lapsades): ponts, carreteres, edificis i talussos, i si cal apuntalament. Suport a la població: retirar arbres i vehicles (comprovant que no hi hagi víctimes), obrir vies, netejar i acompanyar persones vulnerables.","refs":[{"ref":"MAN.SVMN.001, § 4.9","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Es tracta de maniobres d’alt risc i alt cost operatiu, que només es realitzen si hi ha indicis clars de presència d’una víctima i sempre amb personal format i equipat per immersió."},{"ref":"MAN.SVMN.001, § 4.10","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"en el cas del Cos de Bombers formen part de la guàrdia GREC (Grup de Recolzament en Estructures Col·lapsades)."},{"ref":"MAN.SVMN.001, § 4.11","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"És imprescindible comprovar que no hi hagi víctimes a l’interior i avaluar possibles riscos addicionals, com fuites de carburant o perill d’incendi."}]}]},{"n":"11","title":"Seguretat: pautes en medi aquàtic, zonificació, LACES i altres riscos","blocks":[{"text":"S''ha d''evitar l''entrada de rescatadors no especialitzats amb onatge superior a 2,5 m al mar, graus superiors a 3 en rius i aigües braves o durant desembossaments. Cal limitar l''entrada a l''aigua i prioritzar maniobres indirectes. EPI aquàtic: element de flotació amb sistema desembragable, casc, neoprè, guants i calçat. Regla «un dins / un fora», visió permanent, guaita aigües amunt i recursos aigües avall.","refs":[{"ref":"MAN.SVMN.001, § 5.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Onatge superior a 2,5 m al mar. o Graus >3 en rius i aigües braves. o Durant maniobres de desembossament."},{"ref":"MAN.SVMN.001, § 5.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Sempre que un bomber entri al medi aquàtic, n’hi ha d’haver un altre a l’exterior preparat per intervenir en cas d’incidència."},{"ref":"MAN.SVMN.001, § 5.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"En actuacions i salvaments en el medi aquàtic, és fonamental establir un guaita aigües amunt."}]},{"text":"Zona calenta: màxim risc, inclou com a mínim la làmina d''aigua, i es divideix en zona d''aigua o crítica (contacte voluntari) i zona humida (marges i riberes amb risc de contacte involuntari). LACES: L observador, A punts d''ancoratge, C comunicacions, E rutes d''escapament, S zona segura. Altres riscos: hipotèrmia i hidrocució, elèctric, col·lapse estructural, contaminació, arrossegament i animals perillosos.","refs":[{"ref":"MAN.SVMN.001, § 5.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"És la zona de màxim risc, i engloba com a mínim la làmina d’aigua o qualsevol superfície inestable on hi pot haver contacte amb el medi aquàtic."},{"ref":"MAN.SVMN.001, § 5.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"El protocol LACES (Lookouts, Anchor points, Communications, Escape routes, Safety zones) és una eina útil adaptada als riscos de les inundacions"},{"ref":"MAN.SVMN.001, § 5.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Risc d’hipotèrmia i hidrocució per immersió en aigua freda"}]},{"text":"Detall de LACES: l''observador vigila l''evolució de l''aigua; tota persona exposada ha d''anar subjecta amb una línia desembragable o assegurada; cal establir comunicació clara entre l''interior i l''exterior (visual, verbal o ràdio); abans de començar s''ha de definir la ruta de sortida; i cal determinar una zona segura lliure d''aigua o elevada. Dins la zona calenta, cada intervinent ha de tenir una funció concreta i estar sota supervisió directa, i els vehicles no poden comprometre la retirada. Contra la hipotèrmia: entrada progressiva, temps d''exposició limitat, EPI tèrmic i punts de recuperació tèrmica; abans d''entrar en edificis inundats, reconeixement visual previ; davant animals perillosos, aproximació en embarcació o maniobres indirectes.","refs":[{"ref":"MAN.SVMN.001, § 5.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"A – Punts d’ancoratge: Tota persona que s’exposi a l’aigua ha d’estar subjecta amb una línia desembragable o assegurada, o bé disposar d’un punt de referència segur per a la seva retirada."},{"ref":"MAN.SVMN.001, § 5.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Qualsevol intervinent dins la zona calenta ha de tenir assignada una funció concreta i estar sota supervisió directa."},{"ref":"MAN.SVMN.001, § 5.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"cal accedir a l’aigua de forma progressiva, limitar el temps d’exposició segons la temperatura, utilitzar EPI tèrmic complet i garantir punts de recanvi i recuperació tèrmica."},{"ref":"MAN.SVMN.001, § 5.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Col·lapse estructural: L’aigua debilita murs, fonaments i talussos. Cal fer un reconeixement visual previ abans d’accedir a edificis inundats."}]}]},{"n":"R","title":"Recorda per a l''examen","blocks":[{"text":"Inundacions: risc natural més freqüent i greu a Catalunya i el que més afecta al món; més del 40 % dels desastres naturals.","refs":[{"ref":"MAN.SVMN.001, § 1.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"representen més del 40% de tots els desastres naturals"}]},{"text":"Vallès Occidental 1962: gairebé 1.000 morts. Bages i Baix Llobregat 1971: 21 morts.","refs":[{"ref":"MAN.SVMN.001, § 1.2","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"la riuada del Vallès Occidental de 1962 (amb gairebé 1000 persones mortes)"}]},{"text":"Mesura no estructural més important: cartografia de zones inundables i regulació urbanística.","refs":[{"ref":"MAN.SVMN.001, § 1.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"És l’acció més important a nivell de reducció del risc."}]},{"text":"Període de retorn: T10 = 10 %, T50 = 2 %, T100 = 1 %, T500 = 0,2 % de probabilitat anual.","refs":[{"ref":"MAN.SVMN.001, § 2.4","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"si una zona té un període de retorn de 100 anys, això vol dir que cada any hi ha un 1% de probabilitat que es produeixi una inundació d’aquestes característiques."}]},{"text":"Flash floods: de cabal nul a onada destructiva en minuts. Avisos SMC: escala 0-6, del verd al vermell.","refs":[{"ref":"MAN.SVMN.001, § 2.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Inundacions per avinguda sobtada (flash floods): Són típiques de rieres, torrents i barrancs amb conques petites i pendents acusades."}]},{"text":"Primer, maniobres indirectes; directes només amb formació, EPI i suport. Embarcació amb motor: mai amb víctimes submergides a prop.","refs":[{"ref":"MAN.SVMN.001, § 5.1","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"Es prioritzarà sempre que sigui possible l’ús de maniobres indirectes, sense contacte amb l’aigua."}]},{"text":"Un dins / un fora; guaita aigües amunt; LACES; GREC per a la valoració estructural.","refs":[{"ref":"MAN.SVMN.001, § 5.3","law":"MAN.SVMN.001","url":"https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf","quote":"S – Zona segura: Determinar espai lliure d’aigua o punts elevats on refugiar-se en cas de necessitat."}]}]}]'::jsonb, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf'), 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf', null, null, null, null
  from public.topics t where t.slug = 'bomb-t34-inundacions'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
do $$
declare
  v_owner uuid;
  v_slug text;
  v_n int := 0;
begin
  select id into v_owner from public.profiles
   where role = 'owner' and status = 'active' order by created_at limit 1;
  if v_owner is null then
    raise notice 'No hay persona titular: no se publica nada.';
    return;
  end if;
  perform set_config('request.jwt.claims',
    json_build_object('sub', v_owner, 'role', 'authenticated')::text, true);

  for v_slug in select t.slug from public.topics t
                  join public.topic_notes n on n.topic_id = t.id
                 where t.slug like 'bomb-t%' and n.status <> 'published'
                 order by t.slug loop
    perform public.review_topic_notes(v_slug, 'approved');
    v_n := v_n + public.review_topic_notes(v_slug, 'published');
  end loop;

  perform public.log_admin_action('content.publish_notes', 'exam_bodies',
    'bombers-generalitat',
    jsonb_build_object('notes', v_n,
                       'motivo', 'Petición expresa de joel en el hilo del proyecto (11/11/2026: ampliar apuntes 7-34 con los manuales completos)'));
  perform set_config('request.jwt.claims', '', true);
  raise notice 'Bombers de la Generalitat: % fichas con apuntes publicadas', v_n;
end $$;

commit;
